#!/usr/bin/env bash
# Test for hooks/pre-commit (rules/_all/portable-paths.md): a commit that ADDS
# a machine-specific absolute path (/home/<name>/…, /Users/<name>/…) is
# rejected; the policy file and tests/** are allowlisted; existing content is
# never re-judged; ~/, $HOME and placeholders pass.
#
# The sandbox is a throwaway `git init` repo in a temp dir — the real
# workspace's index and hooks are never touched. The hook is generated by
# `quaqua init` into .git/quaqua-hooks/pre-commit with core.hooksPath pointed
# at .git/quaqua-hooks/.
# Usage: tests/test_pre_commit.sh   (exit 0 = pass)
set -euo pipefail

here="$(cd "$(dirname "$0")" && pwd)"
root="$(cd "$here/.." && pwd -P)"
bin="$root/target/debug/quaqua"
[[ -x $bin ]] || (cd "$root" && cargo build --locked --quiet) >/dev/null 2>&1 || true
export PATH="$root/target/debug:$PATH"
export QUAQUA_BIN="${QUAQUA_BIN:-$bin}"

T=$(mktemp -d "${TMPDIR:-/tmp}/test-pre-commit.XXXXXX")
T=$(cd "$T" && pwd -P)
trap 'rm -rf "$T"' EXIT

fail() { echo "FAIL: $*" >&2; exit 1; }

# herdr stub + env pin: `quaqua init` below runs with HERDR_PANE_ID unset, so
# it asks `herdr pane current` — and init resolves `herdr` via PATH, not
# HERDR_BIN_PATH. Pin both so the real binary/server is unreachable from here.
mkdir -p "$T/bin"
cat > "$T/bin/herdr" <<'STUB'
#!/usr/bin/env bash
echo "herdr $*" >> "${CALLS:-/dev/null}"
exit 0
STUB
chmod +x "$T/bin/herdr"
export HERDR_BIN_PATH="$T/bin/herdr"
export HERDR_SOCKET_PATH="$T/herdr.sock"
export PATH="$T/bin:$PATH"
# `quaqua init` without a <dir> defaults to workspace_root(); pin it so a stray
# call can never reach anh iu's real ~/quaqua.
export QUAQUA_HOME="$T/home"

R="$T/repo"
mkdir -p "$R"
git -C "$R" init -q
git -C "$R" config user.email test@example.invalid
git -C "$R" config user.name test

( unset HERDR_PANE_ID; cd "$R" && "$QUAQUA_BIN" init "$R" ) >"$T/init.log" 2>&1 \
  || fail "quaqua init failed: $(cat "$T/init.log")"

hookdir="$R/.git/quaqua-hooks"
hook="$hookdir/pre-commit"

[[ -f $hook ]] || fail "missing generated hook: .git/quaqua-hooks/pre-commit"
[[ -x $hook ]] || fail "generated hook is not executable"
[[ "$(git -C "$R" config --get core.hooksPath)" == "$hookdir" ]] \
  || fail "quaqua init did not set core.hooksPath to $hookdir (got $(git -C "$R" config --get core.hooksPath))"
# hook_rc — run the hook directly from the sandbox repo (hooks read the index
# of their cwd); stdout+stderr land in $T/out
hook_rc() { local rc=0; (cd "$R" && bash "$hook") >"$T/out" 2>&1 || rc=$?; echo "$rc"; }
commit_rc() { local rc=0; git -C "$R" commit -qm "subject" >"$T/out" 2>&1 || rc=$?; echo "$rc"; }
stage() { git -C "$R" add -A; }
reset_all() { git -C "$R" reset -q --hard HEAD >/dev/null 2>&1 || true; git -C "$R" clean -qfd; }

# baseline: a policy file and a tests/ fixture (the two allowlisted paths)
mkdir -p "$R/tests" "$R/rules/_all" "$R/src"
printf '# portable paths\n' > "$R/rules/_all/portable-paths.md"
printf '#!/usr/bin/env bash\necho baseline\n' > "$R/tests/fixture.sh"
printf '#!/usr/bin/env bash\necho baseline\n' > "$R/src/tool.sh"
printf 'baseline\n' > "$R/README.md"
stage; git -C "$R" commit -qm baseline
echo "ok: sandbox repo initialized (core.hooksPath -> .git/quaqua-hooks)"

# ── 1. an added machine path in a script is rejected ───────────────────────
printf '#!/usr/bin/env bash\ncd /home/alice/project\n' > "$R/src/tool.sh"
stage
[[ $(hook_rc) == 1 ]] || fail "added /home/<user>/ path not rejected (direct run)"
grep -q 'src/tool.sh' "$T/out" || fail "hook output does not name the offending file"
grep -q 'home/alice/project' "$T/out" || fail "hook output does not show the offending line"
grep -q 'portable-paths' "$T/out" || fail "hook output does not point at rules/_all/portable-paths.md"
echo "ok: added /home/<user>/ path -> rejected, file + line + policy named"

# and through a real commit, so the installed hook really fires
[[ $(commit_rc) != 0 ]] || fail "git commit succeeded despite a machine path"
grep -q 'src/tool.sh' "$T/out" || fail "commit output does not name the offending file"
reset_all
echo "ok: real git commit through core.hooksPath -> blocked"

# ── 2. /Users/<user>/ is rejected too (macOS form) ─────────────────────────
printf '#!/usr/bin/env bash\nopen /Users/bob/notes\n' > "$R/src/tool.sh"
stage
[[ $(hook_rc) == 1 ]] || fail "added /Users/<user>/ path not rejected"
grep -q 'Users/bob/notes' "$T/out" || fail "hook output does not show the macOS path"
reset_all
echo "ok: added /Users/<user>/ path -> rejected"

# ── 3. allowlist: tests/** and rules/_all/portable-paths.md ────────────────
printf '#!/usr/bin/env bash\ncd /home/alice/project\n' > "$R/tests/fixture.sh"
stage
[[ $(hook_rc) == 0 ]] || fail "tests/** fixture rejected but must be allowlisted"
echo "ok: tests/** fixture with a machine path -> allowed"

printf '# portable paths\n- never /home/alice/…\n' > "$R/rules/_all/portable-paths.md"
stage
[[ $(hook_rc) == 0 ]] || fail "rules/_all/portable-paths.md rejected but must be allowlisted"
echo "ok: rules/_all/portable-paths.md with the pattern -> allowed"

# the allowlist is exact, not a prefix match: a sibling file is still checked
printf '#!/usr/bin/env bash\ncd /home/alice/project\n' > "$R/tests-helper.sh"
stage
[[ $(hook_rc) == 1 ]] || fail "tests-helper.sh is not under tests/ and must be checked"
reset_all; rm -f "$R/tests-helper.sh"
echo "ok: allowlist is exact (tests-helper.sh still checked)"

# ── 4. portable spellings and placeholders pass ───────────────────────────
{
  printf '#!/usr/bin/env bash\n'
  printf 'a=$HOME/thing\n'
  printf 'b=~/thing\n'
  printf 'c=$(dirname "$0")/thing\n'
  printf 'd=/home/<user>/thing\n'
  printf 'e=/Users/<name>/thing\n'
  printf 'f=/etc/hosts\n'
  printf 'g=/usr/local/bin\n'
} > "$R/src/tool.sh"
stage
[[ $(hook_rc) == 0 ]] || fail "portable spellings/placeholders rejected: $(cat "$T/out")"
reset_all
echo "ok: ~/, \$HOME, \$(dirname \"\$0\"), placeholders, /etc -> allowed"

# ── 5. only ADDED lines are judged (existing violations do not brick) ─────
printf '#!/usr/bin/env bash\ncd /home/legacy/project\n' > "$R/src/legacy.sh"
stage
git -C "$R" commit -q --no-verify -m "legacy violation"   # pre-existing state
printf '#!/usr/bin/env bash\ncd /home/legacy/project\necho more\n' > "$R/src/legacy.sh"
stage
[[ $(hook_rc) == 0 ]] || fail "a clean modification of a legacy-violating file was rejected"
grep -q 'echo more' "$R/src/legacy.sh" || fail "modification did not land"
reset_all
echo "ok: existing violations are not re-judged; clean edits still commit"

# ── 6. renames: content is re-checked only when the commit adds lines ─────
git -C "$R" mv src/legacy.sh src/renamed.sh
stage
[[ $(hook_rc) == 0 ]] || fail "a pure rename re-judged the file's existing content"
printf '#!/usr/bin/env bash\ncd /home/legacy/project\ncd /home/carol/other\n' > "$R/src/renamed.sh"
stage
[[ $(hook_rc) == 1 ]] || fail "rename + added machine path not rejected"
grep -q 'src/renamed.sh' "$T/out" || fail "rename+modify output does not name the new path"
reset_all
echo "ok: pure rename allowed; rename + added machine path rejected under the new name"

# ── 7. binary files pass (no lines to scan) ───────────────────────────────
printf '\x00\x01\x02/home/alice/inside\x00\x03' > "$R/blob.bin"
stage
[[ $(hook_rc) == 0 ]] || fail "binary file rejected"
reset_all; rm -f "$R/blob.bin"
echo "ok: binary diff -> allowed (no added lines)"

# ── 8. empty index, and the unborn-branch first commit ───────────────────
[[ $(hook_rc) == 0 ]] || fail "clean index rejected"
F="$T/fresh"
mkdir -p "$F"; git -C "$F" init -q
git -C "$F" config core.hooksPath "$hookdir"
printf '#!/usr/bin/env bash\ncd /home/dave/x\n' > "$F/first.sh"
git -C "$F" add -A
( cd "$F" && bash "$hook" ) >"$T/out" 2>&1 && fail "unborn-branch first commit with a machine path was allowed"
grep -q 'first.sh' "$T/out" || fail "unborn-branch output does not name the file"
echo "ok: clean index -> allowed; unborn-branch first commit with a machine path -> blocked"

# ── 9. the hook source itself must stay portable ─────────────────────────
if grep -qE '/(home|Users)/[A-Za-z0-9._-]+' "$hook"; then
  fail "generated hook contains a literal machine path"
fi
[[ -x $hook ]] || fail "generated hook is not executable (git needs it to run)"
echo "ok: hook source is free of literal machine paths and is executable"

# ── 10. legacy migration and idempotent refresh ───────────────────────────
M="$T/legacy"
mkdir -p "$M"
git -C "$M" init -q
git -C "$M" config user.email test@example.invalid
git -C "$M" config user.name test
git -C "$M" config core.hooksPath "$M/scripts/hooks"

out=$(unset HERDR_PANE_ID; cd "$M" && "$QUAQUA_BIN" init "$M" 2>&1)
[[ "$(git -C "$M" config --get core.hooksPath)" == "$M/.git/quaqua-hooks" ]] \
  || fail "legacy core.hooksPath was not migrated (got $(git -C "$M" config --get core.hooksPath))"
[[ $out == *"migrated"* ]] || fail "no migration log on legacy hooksPath: $out"
[[ -x "$M/.git/quaqua-hooks/pre-commit" ]] || fail "migrated hook is not executable"

# re-run when already pointing to .git/quaqua-hooks: silent and untouched
out2=$(unset HERDR_PANE_ID; cd "$M" && "$QUAQUA_BIN" init "$M" 2>&1)
[[ "$(git -C "$M" config --get core.hooksPath)" == "$M/.git/quaqua-hooks" ]] \
  || fail "re-run corrupted core.hooksPath"
[[ $out2 != *"migrated"* ]] || fail "re-run logged migration when already migrated: $out2"

# overwrite hook with modified content -> quaqua init refreshes it
echo "# modified" > "$M/.git/quaqua-hooks/pre-commit"
out3=$(unset HERDR_PANE_ID; cd "$M" && "$QUAQUA_BIN" init "$M" 2>&1)
[[ $out3 == *"refreshed"* ]] || fail "modified hook was not refreshed with log: $out3"
cmp -s "$M/.git/quaqua-hooks/pre-commit" "$hook" || fail "refreshed hook content differs from template"
echo "ok: legacy core.hooksPath migrated and hook refresh idempotent"

# ── 11. `init --git-hooks <repo>`: hook-only install into an existing repo ──
H="$T/hooks-only"
mkdir -p "$H"; git -C "$H" init -q
git -C "$H" config user.email test@example.invalid
git -C "$H" config user.name test
printf 'baseline\n' > "$H/README.md"
git -C "$H" add -A; git -C "$H" commit -qm baseline

"$QUAQUA_BIN" init --git-hooks "$H" >"$T/gh.log" 2>&1 \
  || fail "init --git-hooks failed: $(cat "$T/gh.log")"
gh_hook="$H/.git/quaqua-hooks/pre-commit"
[[ -x $gh_hook ]] || fail "--git-hooks did not install an executable pre-commit"
cmp -s "$gh_hook" "$hook" || fail "--git-hooks hook body differs from the workspace one"
[[ "$(git -C "$H" config --get core.hooksPath)" == "$H/.git/quaqua-hooks" ]] \
  || fail "--git-hooks did not set core.hooksPath"
# no workspace sync: only README.md and .git exist in the target
[[ -z "$(find "$H" -mindepth 1 -maxdepth 1 ! -name .git ! -name README.md -print)" ]] \
  || fail "--git-hooks wrote workspace files into the target repo"
echo "ok: --git-hooks installs the same hook and skips the workspace sync"

# the installed hook really fires: dirty commit rejected, clean commit accepted
printf '#!/usr/bin/env bash\ncd /home/someone/x\n' > "$H/tool.sh"
git -C "$H" add -A
if git -C "$H" commit -qm dirty >"$T/out" 2>&1; then
  fail "--git-hooks commit with a machine path was allowed"
fi
grep -q 'tool.sh' "$T/out" || fail "--git-hooks commit output does not name the file"
git -C "$H" reset -q --hard HEAD; git -C "$H" clean -qfd
printf '#!/usr/bin/env bash\ncd "$(dirname "$0")"\n' > "$H/tool.sh"
git -C "$H" add -A
git -C "$H" commit -qm clean >"$T/out" 2>&1 \
  || fail "clean commit through the --git-hooks hook was blocked: $(cat "$T/out")"
echo "ok: --git-hooks rejects a machine-path commit and accepts a clean one"

# idempotent: the second run rewrites neither .git/config nor the hook
cp "$H/.git/config" "$T/gh.config"
cp "$gh_hook" "$T/gh.hook"
"$QUAQUA_BIN" init --git-hooks "$H" >"$T/gh2.log" 2>&1 \
  || fail "--git-hooks re-run failed: $(cat "$T/gh2.log")"
cmp -s "$H/.git/config" "$T/gh.config" || fail "--git-hooks re-run rewrote .git/config"
cmp -s "$gh_hook" "$T/gh.hook" || fail "--git-hooks re-run rewrote the hook"
echo "ok: --git-hooks re-run is a no-op"

# a foreign core.hooksPath is refused untouched
git -C "$H" config core.hooksPath "$H/their-hooks"
if out=$("$QUAQUA_BIN" init --git-hooks "$H" 2>&1); then
  fail "--git-hooks overwrote a foreign core.hooksPath"
fi
[[ "$(git -C "$H" config --get core.hooksPath)" == "$H/their-hooks" ]] \
  || fail "--git-hooks changed a foreign core.hooksPath"
[[ $out == *"refusing"* && $out == *"$H/their-hooks"* ]] \
  || fail "unclear refusal for a foreign core.hooksPath: $out"
echo "ok: --git-hooks refuses a foreign core.hooksPath"

# not a git repo -> clear error, non-zero, nothing written
N="$T/not-a-repo"; mkdir -p "$N"
if out=$("$QUAQUA_BIN" init --git-hooks "$N" 2>&1); then
  fail "--git-hooks accepted a non-repo"
fi
[[ $out == *"is not a git repository"* ]] || fail "unclear non-repo error: $out"
[[ -z "$(ls -A "$N")" ]] || fail "--git-hooks wrote into a non-repo: $(ls -A "$N")"
echo "ok: --git-hooks rejects a non-repo without writing"

echo "PASS"
